config.script:
valid_roles = {"Administrator", "Supervisor"}
user_roles = set(list(self.session.props.auth.user.roles))

if self.view.custom.selection in ('',None):
	function = 'Selecione un formulario para firmar'
	alerts.noValidOption(function)

if not (user_roles & valid_roles):
	function = "Usuario no cuenta con los permisos suficientes para firmar"
	alerts.noValidOption(function)

elif self.view.custom.selection.Status in ('Revisado','Finalizado'):
	function = 'El formulario ya esta firmado'
	alerts.noValidOption(function)

elif not (self.view.custom.ipStation in self.view.custom.ips):
	function = 'No se encuentra en la estacion de trabajo correspondiente para firmar este formulario'
	alerts.noValidOption(function)
else:
	alerts.showAlert(state="warning", title="Firmar PAPO", message="Esta seguro de que desea firmar el puesta a punto?", 
	btnTextPrimary="Si", btnTextSecondary="No", btnActionPrimary="signPapoSup")

