if value is None:
    return []

# Convertimos el dataset en PyDataSet
pyds = system.dataset.toPyDataSet(value)
colNames = pyds.getColumnNames()

out = []
for row in pyds:
    # Acceso seguro a la columna "Status"
    try:
        status = str(row["Status"]).strip().lower()
    except:
        status = ""

    # Definimos estilo si está finalizado
    if status == "finalizado":
        style = {"backgroundColor": "#b7cd7f"}
    else:
        style = {}

    # Aplicamos estilo a todas las celdas de la fila
    row_cells = {}
    for col in colNames:
        row_cells[col] = {"value": row[col], "style": style}

    out.append(row_cells)

return out
